paintRankAtmosphere:
function paintRankAtmosphere(i, el){
  el = el || document.getElementById('rankAtmosBase');
  if(!el || !el.style || typeof el.style.setProperty !== 'function') return;
  const r = RANKS[i]; if(!r) return;
  const v = RANK_VISUALS[r.name] || RANK_VISUALS.ROOKIE;


  const g = v.glow || 0;
  el.style.setProperty('--rk-gem', hexA(v.gem[0], 0.16 + g * 0.62));     
  el.style.setProperty('--rk-metal', hexA(v.metal[1], 0.14 + g * 0.46));  
  el.style.setProperty('--rk-deep', hexA(v.card[0], 0.96));

  el.style.setProperty('--rk-field', hexA(v.gem[0], 0.05 + g * 0.11));
  el.style.setProperty('--rk-ring', hexA(v.metal[0], 0.05 + g * 0.13));
}

rankHaloStyle:
function rankHaloStyle(r){
  const v = RANK_VISUALS[r.name] || RANK_VISUALS.ROOKIE, g = v.glow || 0;
  const two = rankHueDistance(v.gem[0], v.gem[1]) >= 60;
  return '--rk-halo:' + hexA(v.gem[0], 0.22 + g * 0.5) + ';--rk-halo2:' + (two ? hexA(v.gem[1], 0.16 + g * 0.34) : 'transparent') +

    ';--rk-floor:' + hexA(v.gem[0], 0.16 + g * 0.3);
}

rankRailHtml:
function rankRailHtml(p){
  const mine = rankIndexOf(p.rank);
  return RANKS.map((r, i) => {
    const state = i < mine ? 'achieved' : i === mine ? 'current' : 'locked';
    const said = state === 'current' ? 'your rank' : state === 'achieved' ? 'achieved' : 'not yet reached';
    return '<button type="button" class="rank-rail-seg is-' + state + '" onclick="rankGoTo(' + i + ')"' +
      ' aria-label="' + escapeAttr(r.name + ', rank ' + (i + 1) + ' of ' + RANKS.length + ', ' + said) + '">' +
      '<span class="rank-rail-bar" aria-hidden="true"></span>' +
      '<span class="rank-rail-node" aria-hidden="true"></span>' +
      (state === 'current' ? '<span class="rank-rail-you" aria-hidden="true">YOU</span>' : '') +
    '</button>';
  }).join('') + '<span class="rank-rail-thumb" id="rankRailThumb" aria-hidden="true"></span>';
}

rankCardHead:
function rankCardHtml(r, i, p){
  const curIdx = rankIndexOf(p.rank);
  const state = i < curIdx ? 'achieved' : i === curIdx ? 'current' : 'locked';
  const range = rankLevelRangeLabel(r);

  let footer = '';

rankCardCurrent:
if(state === 'current'){
    const span = r.max === Infinity ? null : (r.max - r.min + 1);
    const frac = span ? Math.min(1, ((p.level - r.min) + (p.xpForNext > 0 ? p.currentXP / p.xpForNext : 0)) / span) : (p.xpForNext > 0 ? p.currentXP / p.xpForNext : 0);
    const next = RANKS[i + 1];
    const pct = Math.round(frac * 100);

    const levelsLeft = next ? Math.max(0, next.min - p.level) : 0;
    footer =
      '<div class="rank-progress">' +
        '<div class="rank-progress-top"><span class="rank-progress-lvl">LEVEL ' + p.level + '</span>' +
          '<span class="rank-progress-pct">' + pct + '%</span></div>' +
        '<div class="rank-bar"><span style="width:' + pct + '%"></span></div>' +
        (next ?
          '<div class="rank-next">' +
            '<span class="rank-next-medal" aria-hidden="true">' + rankMedalSvg(next.name, 32) + '</span>' +
            '<span class="rank-next-info">' +
              '<span class="rank-next-label">NEXT · ' + escapeHtml(next.name) + '</span>' +
              '<span class="rank-next-lvl">Level ' + next.min + (levelsLeft > 0 ? '<span class="rank-next-extra"> · ' + levelsLeft + (levelsLeft === 1 ? ' level to go' : ' levels to go') + '</span>' : '') + '</span>' +
            '</span>' +
          '</div>'
        : '<div class="rank-progress-final">Final rank</div>') +
      '</div>';

rankCardTail:
const stateLabel = state === 'current' ? 'CURRENT RANK' : state === 'achieved' ? 'ACHIEVED' : 'LOCKED';
  const aria = r.name + ', rank ' + (i + 1) + ' of ' + RANKS.length + ', ' +
    (state === 'current' ? 'current rank, Level ' + p.level + ', ' : state === 'achieved' ? 'achieved, ' : 'not yet reached, ') +
    range.toLowerCase().replace('-', ' through ') + '.';

  return '<article class="rank-panel rank-' + state + '" role="group" aria-roledescription="rank"' +
      ' aria-label="' + escapeAttr(aria) + '">' +
    '<div class="rank-state">' + stateLabel + '</div>' +
    '<h3 class="rank-title">' + escapeHtml(r.name) + '</h3>' +
    '<div class="rank-range">' + escapeHtml(range) + '</div>' +
    '<div class="rank-medal-wrap" style="' + rankHaloStyle(r) + '">' + rankMedalSvg(r.name, 208, { showcase: true }) + '</div>' +
    '<div class="rank-foot">' + footer + '</div>' +
  '</article>';
}
